    const existing = keys.find((k) => field(k, 'credential_ref') === KEY_REF && field(k, 'retired_at') === null) ?? null;
    if (existing !== null) { key = existing; note(`an active key from ${KEY_REF} is already declared (an earlier run): reused — a second declaration of the same key is refused as already declared`); }
