/* ── 5. THE DOWNLOAD ─────────────────────────────────────────────────────── */
console.log('\n5. THE DOWNLOAD — P. Novák downloads the package as one tar (its digest the record\'s; the event on the action); the customer\'s verifier on the tar with the public key; a copy with one byte flipped inside a .bin entry fails');
const scratch = mkdtempSync(join(tmpdir(), 'eye-b13-act-'));
let tarPath = null;
if (exp === null || pkg === null) bad('no export to download (scene 4 built none)');
else {
  const dl = await downloadAs(pn, novak, exp.id);
  if (!dl.ok) fail('export/download (p.novak)', dl);
  else {
    const d = dl.body.download ?? {};
    const bytes = Buffer.from(String(d.base64 ?? ''), 'base64');
    const digest = sha256(bytes);
    tarPath = join(scratch, String(d.filename ?? `${exp.id}.tar`));
    writeFileSync(tarPath, bytes);
    if (bytes.byteLength === Number(d.byteLength) && digest === d.archiveDigest && digest === pkg.archive_digest && d.filename === `${exp.id}.tar` && d.packageDigest === pkg.package_digest) ok(`P. Novák downloaded ${d.filename}: HTTP ${dl.status}, ${bytes.byteLength} bytes, sha256 ${digest} = the recorded archive digest (the tar rebuilt from the package files and compared before it was served); package digest ${String(d.packageDigest).slice(0, 16)}…, manifest digest ${String(d.manifestDigest).slice(0, 16)}…, expires ${iso(d.expiresAt)}; written to ${tarPath}`);
    else bad(`the download: filename ${d.filename}, ${bytes.byteLength} bytes (declared ${d.byteLength}), sha256 ${digest}, archiveDigest ${d.archiveDigest}, the record's ${pkg.archive_digest}`);
    const entries = tarEntries(bytes);
    const expected = manifest === null ? null : ['manifest.json', ...manifest.objects.map((o) => o.bytes.file).sort()];
    if (expected !== null && JSON.stringify(entries.map((x) => x.name)) === JSON.stringify(expected)) ok(`the tar's entries in the fixed order: ${entries.map((x) => `${x.name} (${x.size} bytes)`).join(', ')} — manifest.json first, then the listed .bin files by name (D2: a deterministic ustar, so the digest is a function of the files and built_at)`);
    else note(`the tar's entries: ${entries.map((x) => `${x.name} (${x.size} bytes)`).join(', ')}`);
    const sigBlock = d.signature ?? null;
    if (sigBlock !== null) note(`the answer's signature block: scheme ${sigBlock.scheme}, key ${sigBlock.key_id}${field(sigBlock, 'purpose') !== null ? `, purpose ${field(sigBlock, 'purpose')}` : ''}${field(sigBlock, 'public_key_pem') !== null ? ', the public key PEM beside it' : ''}`);
    const evd = await lastEvent(exp.id, 'export.downloaded');
    if (evd !== null && evd.actor === novak.principalId && (evd.details?.archive_digest === digest || JSON.stringify(evd.details).includes(digest))) ok(`the event export.downloaded on the action: by P. Novák at ${iso(evd.occurred_at)}, ${JSON.stringify(evd.details).slice(0, 200)}`);
    else bad(`the event export.downloaded: ${evd === null ? 'NONE' : JSON.stringify(evd).slice(0, 200)}`);
    // The customer's verifier on the tar: the entries parsed in memory, the same checks as over a directory, the key-based signature verified with the public key.
    const args = ['--expect-package-digest', pkg.package_digest, ...(publicPem === null ? [] : ['--public-key', PUB_PEM_PATH])];
    const good = runVerifierOnTar(tarPath, ...args);
    if (good.exit === 0 && good.ok === true && good.complete === true && (publicPem === null ? good.signature?.verified === null : good.signature?.verified === true)) ok(`the customer's verifier (node scripts/retention/verify-export.mjs --tar ${basename(tarPath)}${publicPem === null ? '' : ' --public-key …'}): exit 0, ok true, complete true, signature ${JSON.stringify(good.signature)} — "${good.verdictLine}"`);
    else bad(`the verifier on the downloaded tar: exit ${good.exit}, ok ${good.ok}, complete ${good.complete}, failed ${good.failed}, signature ${JSON.stringify(good.signature)} — ${good.verdictLine} ${good.failLines.join(' | ')} ${good.stderr}`);
    const bin = entries.find((x) => x.name.endsWith('.bin') && x.size > 0) ?? null;
    if (bin === null) bad('no .bin entry in the tar to flip');
    else {
      const flipped = Buffer.from(bytes); flipped[bin.offset] ^= 0x01;
      const flippedPath = join(scratch, `${exp.id}.flipped.tar`); writeFileSync(flippedPath, flipped);
      const badRun = runVerifierOnTar(flippedPath, ...args);
      if (badRun.exit === 1 && badRun.ok === false && badRun.failLines.length > 0) ok(`a copy with one byte flipped inside ${bin.name}: exit 1, ok false, failed ${badRun.failed} — "${badRun.verdictLine}"; ${badRun.failLines.map((l) => l.trim().slice(0, 160)).join(' | ')}${badRun.failLines.some((l) => /integrity/.test(l) && l.includes(bin.name)) ? '' : ' (the failing check does not name the flipped entry)'}`);
      else bad(`the verifier on the flipped copy: exit ${badRun.exit}, ok ${badRun.ok}, failed ${badRun.failed} — ${badRun.verdictLine} ${badRun.failLines.join(' | ')}`);
    }
    const denied = await downloadAs(ah, hoffmann, exp.id);
    if (denied.status === 403) ok(`A. Hoffmann's download refused: 403 (retention.export.download is the steward's, the authority's, the administrators' and the auditor's; the analyst is not among the holders)`); else bad(`A. Hoffmann's download answered ${denied.status} ${denied.body?.message ?? ''}`);
  }
}

/* ── 6. THE DELIVERY to the transfer station ─────────────────────────────── */
console.log('\n6. THE DELIVERY to the transfer station — H. Bergmann delivers; the host\'s files; custody.delivered; the DEMONSTRATION RECIPIENT verifies on its side and writes its receipt; H. Bergmann collects it: ACKNOWLEDGED');
if (exp === null || pkg === null || station === null) bad('no export or no transfer station to deliver to');
else {
  const dv = await deliver(exp.id, STATION_KEY);
  if (!dv.ok) fail(`export/deliver to ${STATION_KEY} (h.bergmann)`, dv);
  else {
    const dl = dv.body.delivery ?? {};
    if (field(dl, 'state') === 'delivered' && Number(field(dl, 'attempt')) === 1 && field(dl, 'failure_class') === null) ok(`H. Bergmann delivered: HTTP ${dv.status} — delivery ${short(field(dl, 'delivery_id'))}, state ${field(dl, 'state')}, attempt ${field(dl, 'attempt')} (the first delivery of this package to this station), receipt ${JSON.stringify(field(dl, 'receipt'))} (a transfer station answers later)${field(dl, 'key_state') !== null ? `; the key ${JSON.stringify(field(dl, 'key_state'))}` : ''}`);
    else bad(`the delivery: ${JSON.stringify(dl).slice(0, 300)} — expected delivered, attempt 1`);
    const endpoint = String(field(station, 'endpoint') ?? STATION);
    const dir = join(endpoint, T, D, exp.id);
    const tar = join(dir, 'package.tar'); const sigFile = join(dir, 'package.sig'); const deliveryFile = join(dir, 'delivery.json');
    const present = [tar, sigFile, deliveryFile].filter((p) => existsSync(p));
    if (present.length === 3 && sha256File(tar) === pkg.archive_digest) ok(`the host: ${rel(dir)}/ holds package.tar (${statSync(tar).size} bytes, sha256 the archive digest), package.sig and delivery.json`);
    else bad(`the host: ${present.length}/3 files under ${rel(dir)}${existsSync(tar) ? `; package.tar sha256 ${sha256File(tar)} (the record's ${pkg.archive_digest})` : ''}`);
    const sig = readJson(sigFile); const dj = readJson(deliveryFile);
    if (sig !== null) {
      const sigPem = field(sig, 'public_key_pem') ?? field(field(sig, 'key') ?? field(sig, 'signing_key'), 'public_key_pem');
      const inner = sig.signature ?? sig;
      note(`package.sig: scheme ${field(inner, 'scheme')}, key ${field(inner, 'key_id')}, purpose ${field(sig, 'purpose') ?? field(field(sig, 'key') ?? field(sig, 'signing_key'), 'purpose')}, key state ${JSON.stringify(field(sig, 'key_state') ?? field(field(sig, 'key') ?? field(sig, 'signing_key'), 'state'))}; public key PEM ${sigPem === null ? 'ABSENT' : publicPem !== null && pemOf(sigPem) === pemOf(publicPem) ? 'the one on file' : 'present'}`);
    } else bad('package.sig is not JSON');
    if (dj !== null && dj.delivery_id === field(dl, 'delivery_id') && dj.action_id === exp.id && dj.archive_digest === pkg.archive_digest && dj.package_digest === pkg.package_digest && dj.destination_key === STATION_KEY) ok(`delivery.json — the exchange identity: delivery ${short(dj.delivery_id)} attempt ${dj.attempt ?? '?'}, action ${short(dj.action_id)}, destination ${dj.destination_key}, recipient "${dj.recipient}", purpose "${dj.purpose}", digests package ${String(dj.package_digest).slice(0, 12)}… archive ${String(dj.archive_digest).slice(0, 12)}… manifest ${String(dj.manifest_digest).slice(0, 12)}…, signature ${JSON.stringify(dj.signature ?? { scheme: dj.signature_scheme, key_id: dj.key_id })}, delivered ${iso(dj.delivered_at)}, expires ${iso(dj.expires_at)}; "${String(dj.statement ?? '').slice(0, 160)}"`);
    else bad(`delivery.json: ${JSON.stringify(dj).slice(0, 300)}`);
    const rows = await deliveryRows(exp.id);
    const row = rows.find((r) => r.delivery_id === field(dl, 'delivery_id')) ?? null;
    const evd = await lastEvent(exp.id, 'export.delivered');
    if (row !== null && row.state === 'delivered' && row.archive_digest === pkg.archive_digest && row.signing_key_id === pkg.signing_key_id && evd !== null && (evd.details?.delivery_id === row.delivery_id || JSON.stringify(evd.details).includes(row.delivery_id))) ok(`the ledger (retention.export_deliveries): ${deliveryLine(row)}, archive digest the record's, signed by ${row.signing_key_id}; the event export.delivered at ${iso(evd.occurred_at)} ${JSON.stringify(evd.details).slice(0, 160)}`);
    else bad(`the delivery row ${JSON.stringify(row).slice(0, 200)}; event export.delivered ${evd === null ? 'NONE' : 'present'}`);
    const custody = await custodyDelivered(String(field(dl, 'delivery_id')));
    if (custody.length === Number(pkg.object_count)) ok(`custody.delivered per exported record: ${custody.length} row(s) — ${custody.map((c) => `manifest ${short(c.manifest_id)} (${c.details?.destination_key ?? '?'}, ${c.details?.state ?? '?'})`).join(', ')}`); else bad(`custody.delivered rows: ${custody.length}, the package holds ${pkg.object_count} object(s)`);
    // THE DEMONSTRATION RECIPIENT: a script on this host standing in for the customer's side of the station — it reads delivery.json, runs the
    // customer's verifier on package.tar with the public key, and writes receipt.json beside it. It never talks to the product.
    const rc = spawnSync(process.execPath, [RECIPIENT, endpoint, T, D, exp.id, ...(publicPem === null ? [] : ['--public-key', PUB_PEM_PATH]), '--recipient', STATION_RECIPIENT], { encoding: 'utf8' });
    console.log(String(rc.stdout ?? '').trim().split('\n').map((l) => `      [demonstration recipient] ${l}`).join('\n'));
    const receiptFile = join(dir, 'receipt.json'); const receipt = readJson(receiptFile);
    if (rc.status === 0 && receipt !== null && receipt.verified === true && receipt.archive_digest === pkg.archive_digest && receipt.package_digest === pkg.package_digest && receipt.delivery_id === field(dl, 'delivery_id')) ok(`the demonstration recipient (scripts/retention/transfer-station-recipient.mjs — NOT the product, NOT a production recipient): exit 0; receipt.json written — receipt ${short(receipt.receipt_id)}, recipient "${receipt.recipient}", received ${iso(receipt.received_at)}, verified ${receipt.verified} by "${receipt.verifier}", naming delivery ${short(receipt.delivery_id)} attempt ${receipt.attempt} and both digests`);
    else bad(`the demonstration recipient: exit ${rc.status} ${String(rc.stderr ?? '').slice(0, 200)}; receipt.json ${receipt === null ? 'ABSENT or not JSON' : JSON.stringify(receipt).slice(0, 300)}`);
    const col = await collectReceipt(exp.id, String(field(dl, 'delivery_id')));
    if (!col.ok) fail('collect-receipt (h.bergmann)', col);
    else {
      const ack = col.body.delivery ?? {};
      const row2 = (await deliveryRows(exp.id)).find((r) => r.delivery_id === field(dl, 'delivery_id')) ?? null;
      const eva = await lastEvent(exp.id, 'export.acknowledged');
      if (field(ack, 'state') === 'acknowledged' && row2 !== null && row2.state === 'acknowledged' && row2.acknowledged_at !== null && HEX64.test(String(row2.receipt_digest)) && row2.receipt?.receipt_id === receipt?.receipt_id && eva !== null) ok(`H. Bergmann collected the receipt: HTTP ${col.status} — ACKNOWLEDGED at ${iso(row2.acknowledged_at)}; the receipt recorded as received (digest ${row2.receipt_digest}); the event export.acknowledged at ${iso(eva.occurred_at)}`);
      else bad(`the collect act: ${JSON.stringify(ack).slice(0, 200)}; the row ${JSON.stringify(row2).slice(0, 200)}; event export.acknowledged ${eva === null ? 'NONE' : 'present'}`);
      if (row2 !== null) note(`the receipt as recorded: ${JSON.stringify(row2.receipt)}`);
      note('the exchange is CLOSED with the recipient\'s acknowledgement (DP-47-005: recipient acknowledgement before closure): the product wrote the package and its identity, the recipient verified on its side and answered, the product recorded the answer and moved the delivery to acknowledged — a receipt naming other digests would have moved it to mismatched (the exchange denied, the evidence kept; the harness T1)');
    }
  }
}

/* ── 7. THE PRODUCTION PATH'S GATE ───────────────────────────────────────── */
console.log('\n7. THE PRODUCTION PATH\'S GATE — H. Bergmann attempts the delivery to the https destination: recorded FAILED credential_unbound before any egress');
if (exp === null || pkg === null || httpsDest === null) bad('no export or no https destination for the gate');
else {
  const dv = await deliver(exp.id, HTTPS_KEY);
  const rows = await deliveryRows(exp.id);
  const row = rows.filter((r) => r.destination_key === HTTPS_KEY).at(-1) ?? null;
  const dl = dv.body?.delivery ?? null;
  if (dv.ok && field(dl, 'state') === 'failed' && field(dl, 'failure_class') === 'credential_unbound') ok(`the delivery answered HTTP ${dv.status}: delivery ${short(field(dl, 'delivery_id'))} state ${field(dl, 'state')}, class ${field(dl, 'failure_class')}, attempt ${field(dl, 'attempt')} — a FAILED delivery is a recorded fact (the request and evidence preserved), not a rolled-back one`);
  else if (row !== null && row.state === 'failed' && row.failure_class === 'credential_unbound') ok(`the delivery answered HTTP ${dv.status} (${dv.body?.message ?? ''}); the ledger holds the failed row: ${deliveryLine(row)}`);
  else bad(`expected a failed delivery of class credential_unbound; the route answered ${dv.status} ${dv.body?.message ?? JSON.stringify(dl).slice(0, 200)}; the ledger's row ${JSON.stringify(row).slice(0, 200)}`);
  const evf = await lastEvent(exp.id, 'export.delivery_failed');
  if (row !== null && evf !== null && (evf.details?.delivery_id === row.delivery_id || JSON.stringify(evf.details).includes(row.delivery_id))) ok(`the ledger: ${deliveryLine(row)}; the receipt column holds the failure ${JSON.stringify(row.receipt).slice(0, 200)}; the event export.delivery_failed at ${iso(evf.occurred_at)}`);
  else bad(`the failed delivery's row or event: row ${row === null ? 'NONE' : row.state}, event ${evf === null ? 'NONE' : 'present'}`);
  if (row !== null && !/Bearer |EYE_DST_[A-Z0-9_]+=/.test(JSON.stringify(row))) note(`nothing left this process: the reference ${HTTPS_REF} is not bound in the API's environment, so the gate refused before the egress was built — no DNS lookup, no connection; the row names the reference, never a value`);
  note(`DEMONSTRATION vs PRODUCTION: this is the production kind's gate shown without a network. The activation step: the customer's reachable https endpoint declared, one line ${HTTPS_REF}=<the bearer token> in the API process's environment, then the same delivery act — the egress POSTs the tar with the digests, the scheme, the key id and the signature in its headers, verifies TLS, follows no redirect, and records the endpoint's JSON answer as the receipt (acknowledged when it verifies both digests). The egress path itself — an unresolvable host → transport, a loopback address → egress_refused — is proven by the harness H1`);
}

/* ── 8. THE REVOCATION ───────────────────────────────────────────────────── */
console.log('\n8. THE REVOCATION — H. Bergmann revokes the package: the download refused, a further delivery refused; the deliveries stay recorded; no notice reaches the destination');
if (exp === null || pkg === null) bad('no export to revoke');
else {
  const rv = await revoke(exp.id, 'the package was delivered and acknowledged; it is not to be served again');
  if (rv.ok) ok(`H. Bergmann revoked the package: ${JSON.stringify(rv.body.revocation).slice(0, 200)}; bytes removed ${rv.body.bytes?.removed}; the package directory is ${existsSync(join(vaultRoot('export'), T, D, exp.id)) ? 'PRESENT' : 'GONE'}`); else fail('revoke (h.bergmann)', rv);
  const dl = await downloadAs(pn, novak, exp.id);
  if (dl.status === 409 && /revoked/i.test(String(dl.body?.message ?? ''))) ok(`the download refused: 409 ${dl.body.message}`); else bad(`the download after the revocation answered ${dl.status} ${dl.body?.message ?? ''}`);
  const dv = await deliver(exp.id, STATION_KEY);
  if (dv.status === 409 && /revoked/i.test(String(dv.body?.message ?? ''))) ok(`a further delivery refused: 409 ${dv.body.message}`); else bad(`a delivery after the revocation answered ${dv.status} ${dv.body?.message ?? JSON.stringify(dv.body?.delivery ?? null).slice(0, 200)}`);
  const rd = await exportGet(exp.id);
  if (rd.status === 409) ok(`the read refused: 409 ${rd.body?.message ?? ''}`); else note(`the read after the revocation answered ${rd.status}`);
  const rows = await deliveryRows(exp.id);
  const ls = await deliveriesList(exp.id);
  const listed = ls.ok ? (ls.body.deliveries ?? []) : [];
  if (rows.length >= 2 && rows.some((r) => r.state === 'acknowledged') && rows.some((r) => r.state === 'failed') && (!ls.ok || listed.length === rows.length)) ok(`the deliveries stay recorded (${rows.length}): ${rows.map(deliveryLine).join('; ')}${ls.ok ? ` — the list route (retention.read) serves the same ${listed.length}` : ` — the list route answered ${ls.status}`}`);
  else bad(`the deliveries after the revocation: ${rows.map(deliveryLine).join('; ') || 'none'}; the list route ${ls.status} ${listed.length}`);
  const stationTar = station === null ? null : join(String(field(station, 'endpoint') ?? STATION), T, D, exp.id, 'package.tar');
  note(`no notice reaches the destination: the recipient's copy is out of the product's custody (${stationTar !== null && existsSync(stationTar) ? `the station still holds package.tar and its receipt — the demonstration's record, left in place` : 'the station\'s files as the recipient left them'}); the revocation is recorded and the read route says so — a revocation notice to the destination is recorded honestly as REMAINING`);
}

/* ── 9. THE STATE ────────────────────────────────────────────────────────── */
console.log('\n9. THE STATE — tier/state\'s schedules (the retired one), the tenant\'s keys, the domain\'s destinations, the deliveries of the action');
{
  const st = await tierStateAs(cm, dvorak);
  if (!st.ok) fail('tier/state (m.dvorak)', st);
  else {
    const s = st.body.state;
    ok(`M. Dvořák reads the cold tier's state: HTTP ${st.status}`);
    note(`schedules: ${listLine(s.schedules ?? [], (x) => `${short(x.schedule_id)} ${x.action_kind} of profile "${x.retention_profile}" after ${x.due_after} (${x.state}${x.retired_at ? `, retired ${iso(x.retired_at)}` : ''}; last evaluation ${JSON.stringify(x.last_evaluation ?? {})})`)}`);
    note(`tiers: hot ${s.tiers.hot.manifests} manifest(s) / ${s.tiers.hot.bytes} bytes, archive ${s.tiers.archive.manifests} / ${s.tiers.archive.bytes}; policy ${s.policy.declared ? `declared (version ${s.policy.version})` : 'undeclared'}`);
  }
  const ks = await listKeysAs(pn, novak);
  if (ks.ok) note(`the tenant's signing keys: ${listLine(ks.body.keys ?? [], keyLine)}`); else fail('signing-keys/list (p.novak)', ks);
  const ds = await listDestinationsAs(pn, novak);
  if (ds.ok) note(`the domain's destinations: ${listLine(ds.body.destinations ?? [], destinationLine)}`); else fail('destinations/list (p.novak)', ds);
  if (exp !== null) {
    const ls = await deliveriesList(exp.id);
    if (ls.ok) note(`the deliveries of export ${short(exp.id)}: ${listLine(ls.body.deliveries ?? [], deliveryLine)}`); else fail('deliveries/list (p.novak)', ls);
  }
  note(`the scratch directory ${scratch} holds the downloaded tar and its flipped copy; the station directory keeps this run's package, delivery.json and receipt.json as the demonstration's record`);
}

console.log('\nSHOWN ON THE DEMONSTRATION: the governed SCHEDULE RETIREMENT (the row keeps its evaluation and the actions it opened keep their events; the ledger\'s schedule.retired; an evaluation reads it no more), the DEMONSTRATION KEY declared by reference (the public key recorded and served, the private value never leaving the API process), the two DESTINATION kinds (the transfer station of the disconnected path; the https production kind blocked by its unbound credential), the SIGNED EXPORT (scheme eye-customer-export/2 over the package digest, the archive digest and the expiry recorded at the build), the governed DOWNLOAD of one deterministic tar (verified offline with the public key; a flipped byte detected), the DELIVERY to the transfer station with the product\'s files, the recipient\'s receipt collected and the exchange ACKNOWLEDGED, the production path\'s gate recorded as a FAILED delivery before any egress, and the REVOCATION that refuses the download and further deliveries while the deliveries stay recorded.');
console.log('PROVEN BY THE HARNESS ALONE (apps/api/test/int/phase6-retention-b13.test.ts): the https egress path — an unresolvable host recorded transport, a loopback address egress_refused, no credential value in any row (H1); a receipt naming other digests → mismatched, a receipt that is not JSON → refused with the row kept, a stale receipt of another delivery refused by its delivery_id, a second delivery of the same package accepted with the identical tar (T1); a package file tampered on disk → the download refused 409 and the verifier failing; the expiry refusals of the download and the delivery (A1); an export refused at execution when the active key\'s reference is unbound in the process (E1); a schedule retired twice, an under-length reason, the steward\'s retirement (S1); the declaration refusals of keys and destinations (K1, D1); the holders of every new action (P1).');

await su.end();
console.log(`\n=== ${failureCount() === 0 ? 'the act completed with every scene producing its effect' : `${failureCount()} scene step(s) did not produce the effect claimed`} ===`);
process.exit(failureCount() === 0 ? 0 : 1);
